		[rules] = 뒤쪽 같은 레인 반경 45 안의 가장 가까운 다른 배치 아군 1명을 보호 대상으로 정한다. 자신·소환수·타워·현혹 개체·기지는 대상에서 제외한다. 보호자가 생존하고 행동 가능한 상태일 때만 적용하며, 보호자가 원래 무적·공격 대상 제외·별도 차원 상태이면 피해를 대신 받지 않는다.
보호 대상에게 들어오는 원본 적 일반 공격 또는 공격 스킬의 직접 피해가 기존 방어·각성 방어를 거친 뒤의 값을 D라 한다. 해당 피해의 p%=8/12/16/18/20%를 전가하되, 실제 전가량 T는 보호자의 현재 소모 가능한 보호막+현재 HP보다 클 수 없다. 원래 아군은 D-T, 보호자는 T를 받는다. 보호자에게 전가한 T에는 다시 회피·막기·피해 감소·W06 전가를 적용하지 않는다. 보호막부터 정상 소모하고 나머지를 HP에서 차감한다. 부족한 보호 능력만큼은 원래 아군이 받으므로 피해를 삭제하지 않는다. 보호자도 쓰러질 수 있다.
같은 피해에 보호자 여러 명이 나눠 개입하지 않는다. 한 아군의 보호자는 높은 각성 단계→가까운 거리→안정 ID 순서로 1명만 결정한다. 전가 피해는 transfer 태그를 붙여 반사·피격 각성·각인·아이템·흡혈·회복을 새로 발생시키지 않는다. 두 W06 보유자가 서로 보호해도 전가된 피해는 다시 전가되지 않는다. 원본 공격이 두 유닛을 모두 맞히면 각자의 원래 피해는 각각 정상 처리한다. 지속 피해·자해·체력 비용·강제 처형·고정 기믹 피해는 전가하지 않는다. 전가 자체는 파티 총 피해를 줄이지 않으므로 피해 감소 40% 예산과 별개다. 원래 아군에서 이미 적용된 감소량은 전가 과정에서 다시 적용하지 않는다.,
